sp_widget.client_script:
api.controller = function($sce,spContextManager) {

    var c = this;

	spContextManager.addContext('agent-chat', {
		hr_category: "",
		hr_subject: "",
		hr_description: ""
	});

    c.showCaseCreation = false;
    c.caseCreated = false;

    c.rejectionReason = "";
    c.createdCaseNumber = "";

    c.processing = false;
    c.searching = false;

    c.message = "";
    c.messageType = "";

    c.showSolution = false;
    c.solutionFound = false;
    c.solution = {};

    c.form = {
        category: "",
        subject: "",
        description: ""
    };


    // -----------------------------------
    // FIND KNOWLEDGE SOLUTION
    // -----------------------------------

    c.findSolution = function() {

        c.message = "";
        c.messageType = "";

        if (!c.form.category) {

            c.message =
                "Please select an HR case category.";

            c.messageType = "error";
            return;
        }

        if (!c.form.subject ||
            c.form.subject.trim() == "") {

            c.message =
                "Please enter a subject.";

            c.messageType = "error";
            return;
        }

        if (!c.form.description ||
            c.form.description.trim() == "") {

            c.message =
                "Please describe your HR issue.";

            c.messageType = "error";
            return;
        }

        c.showSolution = true;
        c.searching = true;


		spContextManager.updateContextForKey('agent-chat', {
			hr_category: c.form.category,
			hr_subject: c.form.subject,
			hr_description: c.form.description
		});


        c.server.get({

            action: 'find_solution',

            category:
                c.form.category,

            subject:
                c.form.subject,

            description:
                c.form.description

        }).then(function(response) {

            c.searching = false;

            c.solutionFound =
                response.data.solutionFound;

            c.solution =
                response.data.solution || {};

            if (c.solution.text) {

                c.solution.text =
                    $sce.trustAsHtml(
                        c.solution.text
                    );
            }

        });
    };


    // -----------------------------------
    // BACK TO EDIT REQUEST
    // -----------------------------------

    c.backToForm = function() {

        c.showSolution = false;
        c.showCaseCreation = false;

        c.message = "";
        c.messageType = "";
    };


    // -----------------------------------
    // SOLUTION ACCEPTED
    // -----------------------------------

    c.solutionAccepted = function() {

        c.message =
            "Great! Your issue was resolved using the HR Knowledge Base. No HR case was created.";

        c.messageType = "success";

        c.showSolution = false;
        c.showCaseCreation = false;

        c.form = {
            category: "",
            subject: "",
            description: ""
        };

        c.rejectionReason = "";
    };


    // -----------------------------------
    // SOLUTION REJECTED
    // -----------------------------------

    c.solutionRejected = function() {

        c.message = "";
        c.messageType = "";

        c.showSolution = false;
        c.showCaseCreation = true;
    };


    // -----------------------------------
    // BACK TO SOLUTION
    // -----------------------------------

    c.backToSolution = function() {

        c.showCaseCreation = false;
        c.showSolution = true;

        c.message = "";
        c.messageType = "";
    };


    // -----------------------------------
    // CREATE HR CASE
    // -----------------------------------

    c.createCase = function() {

        c.message = "";
        c.messageType = "";

        if (!c.rejectionReason ||
            c.rejectionReason.trim() == "") {

            c.message =
                "Please explain why the suggested solution did not help.";

            c.messageType = "error";
            return;
        }

        if (c.processing)
            return;

        c.processing = true;

        c.server.get({

            action: 'create_case',

            category:
                c.form.category,

            subject:
                c.form.subject,

            description:
                c.form.description,

            rejectionReason:
                c.rejectionReason

        }).then(function(response) {

            c.processing = false;

            if (response.data.caseCreated) {

                c.showCaseCreation = false;
                c.showSolution = false;
                c.caseCreated = true;

                c.createdCaseNumber =
                    response.data.caseNumber;

            } else {

                c.message =
                    response.data.error ||
                    "Unable to create the HR case.";

                c.messageType = "error";
            }

        });
    };

};

sp_widget.css:
.raise-case-page {
  max-width: 1000px;
  margin: 0 auto;
  padding: 36px 30px 60px;
  min-height: 100vh;
  background: #f7f9fc;
  color: #0f1b45;
}

.case-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 24px;
}

.case-header h2 {
  margin: 0 0 7px;
  font-size: 28px;
  font-weight: 700;
  color: #0f1b45;
}

.case-header p {
  margin: 0;
  color: #7d879c;
  font-size: 13px;
}

.back-link {
  color: #1769e0;
  text-decoration: none;
  font-size: 12px;
  font-weight: 600;
}

.case-form-card {
  background: #ffffff;
  border: 1px solid #e1e6ee;
  border-radius: 15px;
  padding: 28px;
  box-shadow: 0 5px 18px rgba(15,27,69,.05);
}

.form-group {
  margin-bottom: 22px;
}

.form-group label {
  display: block;
  margin-bottom: 8px;
  color: #1d2947;
  font-size: 12px;
  font-weight: 700;
}

.form-group label span {
  color: #dc2626;
}

.form-control {
  width: 100%;
  border: 1px solid #d9e0e9;
  border-radius: 9px;
  padding: 11px 13px;
  font-size: 13px;
  box-shadow: none;
}

.form-control:focus {
  border-color: #0b8793;
  box-shadow: 0 0 0 2px rgba(11,135,147,.08);
}

.description-box {
  min-height: 130px;
  resize: vertical;
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  padding-top: 8px;
}

.solution-btn {
  border: none;
  border-radius: 9px;
  padding: 11px 20px;
  background: #0b8793;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.solution-btn:hover {
  background: #08727b;
}

.solution-btn:disabled {
  opacity: .6;
  cursor: not-allowed;
}

.case-message {
  padding: 13px 16px;
  margin-bottom: 18px;
  border-radius: 9px;
  font-size: 12px;
}

.case-message.success {
  background: #ecfdf3;
  border: 1px solid #a7f3d0;
  color: #166534;
}

.case-message.error {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #991b1b;
}

.solution-card {
  background: #ffffff;
  border: 1px solid #e1e7ef;
  border-radius: 15px;
  padding: 28px;
  box-shadow: 0 5px 18px rgba(15,27,69,.05);
}

.solution-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 20px;
  margin-bottom: 22px;
}

.solution-header h3 {
  margin: 10px 0 5px;
  color: #0f1b45;
  font-size: 21px;
}

.solution-header p {
  margin: 0;
  color: #758198;
  font-size: 12px;
}

.solution-badge {
  display: inline-block;
  background: #dcfce7;
  color: #15803d;
  padding: 6px 10px;
  border-radius: 20px;
  font-size: 10px;
  font-weight: 700;
}

.edit-request-btn {
  border: 1px solid #dce3ec;
  background: #ffffff;
  color: #1769e0;
  border-radius: 8px;
  padding: 8px 12px;
  font-size: 11px;
}

.knowledge-result {
  background: linear-gradient(135deg, #effcf5, #eef9ff);
  border: 1px solid #b8ead1;
  border-radius: 12px;
  padding: 22px;
}

.knowledge-source {
  color: #15803d;
  font-size: 10px;
  font-weight: 700;
  margin-bottom: 8px;
}

.knowledge-result h4 {
  margin: 0 0 14px;
  color: #172554;
  font-size: 17px;
}

.knowledge-content {
  color: #40506a;
  font-size: 12px;
  line-height: 1.7;
}

.knowledge-number {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid rgba(22,101,52,.12);
  color: #64748b;
  font-size: 10px;
}

.solution-question {
  margin-top: 20px;
  padding-top: 20px;
  border-top: 1px solid #edf1f5;
}

.solution-question h4 {
  margin: 0 0 5px;
  color: #172554;
}

.solution-question p {
  color: #758198;
  font-size: 11px;
}

.solution-actions {
  display: flex;
  gap: 12px;
  margin-top: 16px;
}

.resolved-btn,
.continue-btn {
  border-radius: 8px;
  padding: 10px 16px;
  font-size: 11px;
  font-weight: 700;
}

.resolved-btn {
  border: none;
  background: #16a34a;
  color: #ffffff;
}

.continue-btn {
  border: 1px solid #0b8793;
  background: #ffffff;
  color: #0b8793;
}

.no-solution {
  text-align: center;
  padding: 35px 20px;
  background: #f8fafc;
  border-radius: 12px;
}

.no-solution-icon {
  font-size: 36px;
  margin-bottom: 10px;
}

.no-solution h4 {
  color: #172554;
}

.no-solution p {
  color: #64748b;
  font-size: 12px;
  margin-bottom: 18px;
}

.solution-loading {
  padding: 35px;
  text-align: center;
  color: #64748b;
}

.case-help-text {
  color: #64748b;
  font-size: 12px;
  margin-bottom: 18px;
}

.case-summary {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 14px;
  margin: 18px 0;
}

.case-summary > div {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  padding: 12px;
  border-radius: 9px;
}

.case-summary span {
  display: block;
  font-size: 10px;
  color: #64748b;
  margin-bottom: 5px;
}

.case-summary strong {
  color: #172554;
  font-size: 12px;
}

.case-created-card {
  background: #ffffff;
  border: 1px solid #dfe6ee;
  border-radius: 15px;
  padding: 45px;
  text-align: center;
}

.created-icon {
  width: 55px;
  height: 55px;
  margin: 0 auto 15px;
  border-radius: 50%;
  background: #dcfce7;
  color: #15803d;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 27px;
  font-weight: 700;
}

.created-number {
  display: inline-block;
  margin: 16px 0 22px;
  padding: 10px 18px;
  border-radius: 20px;
  background: #eef2ff;
  color: #3730a3;
  font-size: 16px;
  font-weight: 700;
}

.created-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
}

sp_widget.script:
(function() {

    data.categories = [];


    // -----------------------------------
    // LOAD HR CASE CATEGORIES
    // -----------------------------------

    var choiceGR = new GlideRecord('sys_choice');

    choiceGR.addQuery(
        'name',
        'x_snc_unified_hr_0_hr_case'
    );

    choiceGR.addQuery(
        'element',
        'category'
    );

    choiceGR.addQuery(
        'inactive',
        false
    );

    choiceGR.orderBy('sequence');
    choiceGR.query();

    while (choiceGR.next()) {

        data.categories.push({

            label:
                choiceGR.getValue('label'),

            value:
                choiceGR.getValue('value')

        });
    }


    // -----------------------------------
    // SEARCH HR KNOWLEDGE
    // -----------------------------------

    if (input && input.action == 'find_solution') {

        data.solutionFound = false;
        data.solution = {};

        var subject =
            (input.subject || '').trim();

        var description =
            (input.description || '').trim();

        var searchText =
            subject + " " + description;

        var words = searchText
            .toLowerCase()
            .replace(/[^a-z0-9 ]/g, ' ')
            .split(/\s+/);

        var stopWords = {
            'the': true,
            'is': true,
            'a': true,
            'an': true,
            'and': true,
            'or': true,
            'to': true,
            'of': true,
            'for': true,
            'in': true,
            'on': true,
            'my': true,
            'i': true,
            'me': true,
            'with': true,
            'what': true,
            'how': true,
            'can': true,
            'do': true
        };

        var keywords = [];

        for (var i = 0; i < words.length; i++) {

            var word = words[i];

            if (
                word.length >= 4 &&
                !stopWords[word] &&
                keywords.indexOf(word) == -1
            ) {
                keywords.push(word);
            }
        }


        var kbGR =
            new GlideRecord('kb_knowledge');

        kbGR.addQuery(
            'workflow_state',
            'published'
        );


        if (keywords.length > 0) {

            var queryString = '';

            for (var j = 0; j < keywords.length; j++) {

                if (queryString != '') {
                    queryString += '^OR';
                }

                queryString +=
                    'short_descriptionLIKE' +
                    keywords[j];

                queryString +=
                    '^ORtextLIKE' +
                    keywords[j];
            }

            kbGR.addEncodedQuery(queryString);

        } else {

            kbGR.addQuery(
                'short_description',
                'CONTAINS',
                subject
            );
        }


        kbGR.orderByDesc('sys_updated_on');
        kbGR.setLimit(1);
        kbGR.query();


        if (kbGR.next()) {

            data.solutionFound = true;

            data.solution = {

                sys_id:
                    kbGR.getUniqueValue(),

                number:
                    kbGR.getDisplayValue('number'),

                short_description:
                    kbGR.getDisplayValue(
                        'short_description'
                    ),

                text:
                    kbGR.getValue('text')

            };
        }
    }


    // -----------------------------------
    // CREATE HR CASE
    // -----------------------------------

    if (input && input.action == 'create_case') {

        data.caseCreated = false;
        data.caseNumber = "";
        data.caseSysId = "";
        data.error = "";


        if (
            !input.category ||
            !input.subject ||
            !input.description ||
            !input.rejectionReason
        ) {

            data.error =
                "Required case information is missing.";

            return;
        }


        var caseGR =
            new GlideRecord(
                'x_snc_unified_hr_0_hr_case'
            );

        caseGR.initialize();


        caseGR.setValue(
            'request_by',
            gs.getUserID()
        );

        caseGR.setValue(
            'category',
            input.category
        );

        caseGR.setValue(
            'subject',
            input.subject
        );

        caseGR.setValue(
            'description',
            input.description
        );

        caseGR.setValue(
            'rejection_feedback',
            input.rejectionReason
        );

        caseGR.setValue(
            'status',
            'open'
        );


        var newSysId =
            caseGR.insert();


        if (newSysId) {

            data.caseCreated = true;
            data.caseSysId = newSysId;

            if (caseGR.get(newSysId)) {

                data.caseNumber =
                    caseGR.getDisplayValue(
                        'number'
                    );
            }

        } else {

            data.error =
                "Unable to create the HR case.";
        }
    }

})();
